using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.DependencyInjection;using MyFundex.BuildingBlocks.Abstractions;using MyFundex.BuildingBlocks.Domain;using MyFundex.BuildingBlocks.Persistence;
namespace MyFundex.Withdrawals;
public sealed class WithdrawalRequest:EntityBase{public Guid WithdrawalId{get;set;}public long FundedAccountInternalId{get;set;}public decimal RequestedAmount{get;set;}public decimal EligibleAmount{get;set;}public decimal NetPayoutAmount{get;set;}public string Status{get;set;}="Requested";public DateTimeOffset RequestedAt{get;set;}=DateTimeOffset.UtcNow;}
public sealed class WithdrawalCalculation:EntityBase{public Guid CalculationId{get;set;}public long WithdrawalInternalId{get;set;}public decimal GrossProfit{get;set;}public decimal TaxAmount{get;set;}public decimal PlatformFee{get;set;}public decimal PlatformFeeTax{get;set;}public decimal ProfitAfterDeductions{get;set;}public decimal TraderSharePercentage{get;set;}public decimal TraderEntitlement{get;set;}public decimal CompanyShare{get;set;}public Guid PolicyVersionId{get;set;}}
public sealed class WithdrawalDbContext(DbContextOptions<WithdrawalDbContext>o,ICurrentActor a):AuditableDbContext(o,a){public DbSet<WithdrawalRequest>Requests=>Set<WithdrawalRequest>();public DbSet<WithdrawalCalculation>Calculations=>Set<WithdrawalCalculation>();protected override void OnModelCreating(ModelBuilder m){m.HasDefaultSchema("withdrawal");ConfigureEntity(m.Entity<WithdrawalRequest>());ConfigureEntity(m.Entity<WithdrawalCalculation>());m.Entity<WithdrawalRequest>().HasIndex(x=>x.WithdrawalId).IsUnique();}}
public static class WithdrawalsModule{public static IServiceCollection AddWithdrawalsModule(this IServiceCollection s,string cs){s.AddDbContext<WithdrawalDbContext>(o=>o.UseNpgsql(cs));return s;}}
